import java.nio.ByteBuffer;

private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    byte b = bb.get(i);
    if ((b & 0x80) == 0) { // 1-byte character
        sb.append((char) b);
        return i + 1;
    } else if ((b & 0xE0) == 0xC0 && (bb.get(i + 1) & 0xC0) == 0x80) { // 2-byte character
        char ch = (char) (((b & 0x1F) << 6) + (bb.get(i + 1) & 0x3F));
        sb.append(ch);
        return i + 2;
    } else if ((b & 0xF0) == 0xE0 && (bb.get(i + 1) & 0xC0) == 0x80 && (bb.get(i + 2) & 0xC0) == 0x80) { // 3-byte character
        char ch = (char) (((b & 0x0F) << 12) + ((bb.get(i + 1) & 0x3F) << 6) + (bb.get(i + 2) & 0x3F));
        sb.append(ch);
        return i + 3;
    } else if ((b & 0xF8) == 0xF0 && (bb.get(i + 1) & 0xC0) == 0x80 && (bb.get(i + 2) & 0xC0) == 0x80 && (bb.get(i + 3) & 0xC0) == 0x80) { // 4-byte character
        int codePoint = (((b & 0x07) << 18) + ((bb.get(i + 1) & 0x3F) << 12) + ((bb.get(i + 2) & 0x3F) << 6) + (bb.get(i + 3) & 0x3F));
        sb.append(Character.toChars(codePoint));
        return i + 4;
    }
    return i + 1; // Invalid character, skip it
}

