import org.jgrapht.Graph;
import org.jgrapht.graph.DefaultEdge;
import org.jgrapht.generate.GraphGenerator;

import java.util.Map;

public class CompleteBipartiteGraphGenerator<V, E extends DefaultEdge> implements GraphGenerator<V, E, V> {

    private final int partitionOneSize;
    private final int partitionTwoSize;

    public CompleteBipartiteGraphGenerator(int partitionOneSize, int partitionTwoSize) {
        this.partitionOneSize = partitionOneSize;
        this.partitionTwoSize = partitionTwoSize;
    }

    @Override
    public void generateGraph(Graph<V, E> target, Map<String, V> resultMap, VertexFactory<V> vertexFactory) {
        if (resultMap == null) {
            resultMap = createResultMap();
        }

        // Create vertices for the first partition
        V[] partitionOne = createVertices(partitionOneSize, resultMap, vertexFactory, "A");

        // Create vertices for the second partition
        V[] partitionTwo = createVertices(partitionTwoSize, resultMap, vertexFactory, "B");

        // Add edges between vertices of the two partitions
        for (V vertexOne : partitionOne) {
            for (V vertexTwo : partitionTwo) {
                target.addEdge(vertexOne, vertexTwo);
            }
        }
    }

    private V[] createVertices(int size, Map<String, V> resultMap, VertexFactory<V> vertexFactory, String prefix) {
        V[] vertices = (V[]) new Object[size];
        for (int i = 0; i < size; i++) {
            V vertex = vertexFactory.createVertex();
            String label = prefix + (i + 1);
            vertices[i] = vertex;
            resultMap.put(label, vertex);
            target.addVertex(vertex);
        }
        return vertices;
    }

    private Map<String, V> createResultMap() {
        return new java.util.HashMap<>();
    }

    public interface VertexFactory<V> {
        V createVertex();
    }
}
