import java.util.HashMap;
import java.util.Map;

public class Mappings {
    private Map<String, Object> fields;

    public Mappings(Map<String, Object> fields) {
        this.fields = fields;
    }

    public Map<String, Object> getFields() {
        return fields;
    }

    public Mappings diffStructure(String tableName, Mappings mappings) {
        Map<String, Object> diffFields = new HashMap<>();
        Map<String, Object> currentFields = this.fields;
        Map<String, Object> historyFields = mappings.getFields();

        for (Map.Entry<String, Object> entry : currentFields.entrySet()) {
            String key = entry.getKey();
            if (!historyFields.containsKey(key) && !"_source".equals(key)) {
                diffFields.put(key, entry.getValue());
            }
        }

        return new Mappings(diffFields);
    }

    public static void main(String[] args) {
        Map<String, Object> currentFields = new HashMap<>();
        currentFields.put("field1", "value1");
        currentFields.put("field2", "value2");
        currentFields.put("_source", "sourceValue");

        Map<String, Object> historyFields = new HashMap<>();
        historyFields.put("field1", "value1");

        Mappings currentMappings = new Mappings(currentFields);
        Mappings historyMappings = new Mappings(historyFields);

        Mappings diffMappings = currentMappings.diffStructure("tableName", historyMappings);
        System.out.println(diffMappings.getFields()); // Output: {field2=value2}
    }
}
