public class ArrayComparator {
    /**
     * Returns true if the contents of the internal array and the provided array match.
     */
    public boolean equals(final byte[] internalArray, final byte[] data, int offset, final int len) {
        if (internalArray == null || data == null) {
            return false;
        }
        if (internalArray.length < len || data.length < offset + len) {
            return false;
        }
        for (int i = 0; i < len; i++) {
            if (internalArray[i] != data[offset + i]) {
                return false;
            }
        }
        return true;
    }

    public static void main(String[] args) {
        ArrayComparator comparator = new ArrayComparator();
        byte[] internalArray = {1, 2, 3, 4, 5};
        byte[] data = {0, 0, 1, 2, 3, 4, 5};
        int offset = 2;
        int len = 5;
        System.out.println(comparator.equals(internalArray, data, offset, len)); // Output: true
