import org.apache.log4j.spi.LoggingEvent;

public class LoggingBuffer {
    private LoggingEvent[] buffer;
    private int head;
    private int tail;
    private int size;
    private int capacity;

    public LoggingBuffer(int capacity) {
        this.capacity = capacity;
        this.buffer = new LoggingEvent[capacity];
        this.head = 0;
        this.tail = 0;
        this.size = 0;
    }

    public void put(LoggingEvent o) {
        if (size < capacity) {
            buffer[head] = o;
            head = (head + 1) % capacity;
            size++;
        }
    }

    public static void main(String[] args) {
        LoggingBuffer logBuffer = new LoggingBuffer(5);
        LoggingEvent event = new LoggingEvent("LoggerName", null, 1, org.apache.log4j.Level.INFO, "This is a log message", null);
        logBuffer.put(event);
    }
}
