import java.nio.charset.StandardCharsets;

public class UTF8SizeCalculator {
    public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
        int size = 0;
        for (int i = index; i < index + len; i++) {
            char c = str.charAt(i);
            if (c <= 0x7F) {
                size += 1;
            } else if (c <= 0x7FF) {
                size += 2;
            } else if (Character.isSurrogate(c)) {
                size += 4; // surrogate pair
                i++; // skip the next character as it's part of the surrogate pair
            } else {
                size += 3;
            }
        }
        return size;
    }

    public static void main(String[] args) {
        CharSequence str = "Hello, world! 🌍";
        int index = 0;
        int len = str.length();
        System.out.println(computeUTF8Size(str, index, len)); // Output the size of the UTF-8 encoded string
    }
