import java.util.Arrays;

public class ByteVector {
    private byte[] data;
    private int length;

    public ByteVector() {
        this.data = new byte[64];
        this.length = 0;
    }

    public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {
        if (byteLength > 0) {
            ensureCapacity(byteLength);
            if (byteArrayValue == null) {
                Arrays.fill(data, length, length + byteLength, (byte) 0);
            } else {
                System.arraycopy(byteArrayValue, byteOffset, data, length, byteLength);
            }
            length += byteLength;
        }
        return this;
    }

    private void ensureCapacity(final int byteLength) {
        int neededCapacity = length + byteLength;
        if (data.length < neededCapacity) {
            int newCapacity = Math.max(2 * data.length, neededCapacity);
            byte[] newData = new byte[newCapacity];
            System.arraycopy(data, 0, newData, 0, length);
            data = newData;
        }
    }

    public byte[] getData() {
        return Arrays.copyOf(data, length);
    }

    public int getLength() {
        return length;
    }
}
