import java.util.Properties;

public static String findAndSubst(String key, Properties props) {
    String value = props.getProperty(key);
    if (value != null) {
        value = substituteVariables(value, props);
    }
    return value;
}

private static String substituteVariables(String value, Properties props) {
    StringBuilder result = new StringBuilder();
    int varStart = value.indexOf("${");
    int varEnd = value.indexOf("}", varStart);
    int lastEnd = 0;

    while (varStart != -1 && varEnd != -1) {
        result.append(value, lastEnd, varStart);
        String varName = value.substring(varStart + 2, varEnd);
        String varValue = props.getProperty(varName);
        if (varValue != null) {
            result.append(varValue);
        } else {
            result.append("${").append(varName).append("}");
        }
        lastEnd = varEnd + 1;
        varStart = value.indexOf("${", lastEnd);
        varEnd = value.indexOf("}", varStart);
    }

    result.append(value.substring(lastEnd));
    return result.toString();
}

