public class PathDecoder {

    public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
        List<PathSegmentImpl> pathSegments = new ArrayList<>();
        String path = u.getRawPath();

        if (path == null || path.isEmpty()) {
            return pathSegments;
        }

        // Ignore leading '/'
        if (path.charAt(0) == '/') {
            path = path.substring(1);
        }

        String[] segments = path.split("/");
        for (String segment : segments) {
            if (decode) {
                try {
                    segment = java.net.URLDecoder.decode(segment, "UTF-8");
                } catch (java.io.UnsupportedEncodingException e) {
                    // Handle the exception according to your needs
                }
            }
            pathSegments.add(new PathSegmentImpl(segment));
        }

        return pathSegments;
    }

    // Assuming PathSegmentImpl is a simple class with a constructor that takes a String
    public static class PathSegmentImpl {
        private String path;

        public PathSegmentImpl(String path) {
            this.path = path;
        }

        // You can override toString() or other methods if needed
        @Override
        public String toString() {
            return path;
        }
    }

    public static void main(String[] args) throws URISyntaxException {
        URI uri = new URI("https://example.com/path/to/resource");
        List<PathSegmentImpl> segments = decodePath(uri, true);
        for (PathSegmentImpl segment : segments) {
            System.out.println(segment);
        }
    }
