public class FileIterator {
    private File[] files;
    private int index = 0;

    public FileIterator(String directoryPath) {
        File directory = new File(directoryPath);
        if (directory.isDirectory()) {
            files = directory.listFiles();
        } else {
            files = new File[0];
        }
    }

    public InputStream next() throws IOException {
        if (files == null || index >= files.length) {
            return null;
        }
        File file = files[index++];
        if (file.isFile()) {
            return new FileInputStream(file);
        }
        return next(); // Skip directories and try the next file
    }

    public static void main(String[] args) {
        FileIterator iterator = new FileIterator("/path/to/directory");
        InputStream inputStream;
        try {
            while ((inputStream = iterator.next()) != null) {
                // Process the input stream
                inputStream.close();
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}
