import java.util.Stack;

private void pop(final String descriptor) {
    Stack<Object> outputFrameStack = new Stack<>();
    int currentPos = 0;
    while (currentPos < descriptor.length()) {
        char type = descriptor.charAt(currentPos++);
        switch (type) {
            case 'B':
            case 'C':
            case 'I':
            case 'S':
            case 'Z':
            case 'F':
                outputFrameStack.pop();
                break;
            case 'D':
            case 'J':
                outputFrameStack.pop();
                outputFrameStack.pop();
                break;
            case 'L':
                while (descriptor.charAt(currentPos++) != ';') {
                    // Skip the class name
                }
                outputFrameStack.pop();
                break;
            case '[':
                while (descriptor.charAt(currentPos) == '[') {
                    currentPos++;
                }
                if (descriptor.charAt(currentPos) == 'L') {
                    currentPos++; // Skip the 'L'
                    while (descriptor.charAt(currentPos++) != ';') {
                        // Skip the class name
                    }
                } else {
                    currentPos++;
                }
                outputFrameStack.pop();
                break;
            case '(':
                int endOfParams = descriptor.indexOf(')', currentPos);
                String parameterTypes = descriptor.substring(currentPos, endOfParams);
                pop(parameterTypes);
                currentPos = endOfParams + 1;
                char returnType = descriptor.charAt(currentPos);
                if (returnType == 'V') {
                    // No return type, do nothing
                } else {
                    // Push the return type back onto the stack if it's not void
                    // Since we're popping, we don't need to do anything here
                }
                break;
            default:
                throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
        }
    }
}
