public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }

    StringBuilder sb = new StringBuilder();
    boolean escaped = false;
    for (int i = 0; i < str.length(); i++) {
        char c = str.charAt(i);
        if (escaped) {
            switch (c) {
                case 'b':
                    sb.append('\b');
                    break;
                case 't':
                    sb.append('\t');
                    break;
                case 'n':
                    sb.append('\n');
                    break;
                case 'f':
                    sb.append('\f');
                    break;
                case 'r':
                    sb.append('\r');
                    break;
                case '"':
                    sb.append('"');
                    break;
                case '\'':
                    sb.append('\'');
                    break;
                case '\\':
                    sb.append('\\');
                    break;
                case 'u':
                    if (i + 4 < str.length()) {
                        String hex = str.substring(i + 1, i + 5);
                        sb.append((char) Integer.parseInt(hex, 16));
                        i += 4; // skip the hex digits
                    } else {
                        throw new Exception("Invalid unicode escape");
                    }
                    break;
                default:
                    sb.append(c);
                    break;
            }
            escaped = false;
        } else {
            if (c == '\\') {
                escaped = true;
            } else {
                sb.append(c);
            }
        }
    }
    return sb.toString();
}

