import java.io.UTFDataFormatException;

final String readUtf(final int constantPoolEntryIndex, final char[] charBuffer) {
    int offset = 1 + 2 * constantPoolEntryIndex; // Assuming each entry is 2 bytes and starts after the first byte
    int utfLength = ((classFileBuffer[offset] & 0xFF) << 8) | (classFileBuffer[offset + 1] & 0xFF);
    offset += 2;
    int charIndex = 0;
    for (int i = 0; i < utfLength; ) {
        int c = classFileBuffer[offset++] & 0xFF;
        switch (c >> 4) {
            case 0:
            case 1:
            case 2:
            case 3:
            case 4:
            case 5:
            case 6:
            case 7:
                // 0xxxxxxx
                charBuffer[charIndex++] = (char) c;
                i++;
                break;
            case 12:
            case 13:
                // 110x xxxx   10xx xxxx
                if (i + 1 >= utfLength) throw new UTFDataFormatException();
                charBuffer[charIndex++] = (char) (((c & 0x1F) << 6) | (classFileBuffer[offset++] & 0x3F));
                i += 2;
                break;
            case 14:
                // 1110 xxxx  10xx xxxx  10xx xxxx
                if (i + 2 >= utfLength) throw new UTFDataFormatException();
                charBuffer[charIndex++] = (char) (((c & 0x0F) << 12) | ((classFileBuffer[offset] & 0x3F) << 6) | ((classFileBuffer[offset + 1] & 0x3F) << 0));
                offset += 2;
                i += 3;
                break;
            default:
                // 10xx xxxx,  1111 xxxx
                throw new UTFDataFormatException();
        }
    }
    return new String(charBuffer, 0, charIndex);
}
