import org.jgrapht.graph.DefaultEdge;

private List<Pair<List<Pair<Integer,Integer>>, DefaultEdge>> computeGlobalSeparatorList(Graph<Integer, DefaultEdge> graph) {
    List<Pair<List<Pair<Integer,Integer>>, DefaultEdge>> globalSeparators = new ArrayList<>();
    MinimalSeparator<Integer, DefaultEdge> minimalSeparator = new MinimalSeparator<>(graph);

    for (DefaultEdge edge : graph.edgeSet()) {
        Set<Integer> separatorSet = minimalSeparator.getMinimalSeparator(edge);
        List<Pair<Integer, Integer>> separators = new ArrayList<>();

        for (Integer vertex : separatorSet) {
            separators.add(Pair.with(vertex, vertex));
        }

        globalSeparators.add(Pair.with(separators, edge));
    }

    return globalSeparators;
}
