public class ByteVector {
    private byte[] data;
    private int length;

    public ByteVector() {
        this.data = new byte[32];
    }

    public ByteVector putInt(final int intValue) {
        ensureCapacity(4);
        data[length++] = (byte) (intValue >>> 24);
        data[length++] = (byte) (intValue >>> 16);
        data[length++] = (byte) (intValue >>> 8);
        data[length++] = (byte) intValue;
        return this;
    }

    private void ensureCapacity(int additional) {
        if (length + additional > data.length) {
            int newSize = Math.max(data.length * 2, length + additional);
            data = Arrays.copyOf(data, newSize);
        }
    }

    @Override
    public String toString() {
        return Arrays.toString(Arrays.copyOf(data, length));
    }

    public static void main(String[] args) {
        ByteVector bv = new ByteVector();
        bv.putInt(123456789).putInt(987654321);
        System.out.println(bv);
    }
