import java.io.File;

public class FileUtils {
    public static int indexOfExtension(String filename) {
        if (filename == null) {
            return -1;
        }
        int lastSeparator = indexOfLastSeparator(filename);
        int lastDot = filename.lastIndexOf('.');
        if (lastDot > lastSeparator) {
            return lastDot;
        } else {
            return -1;
        }
    }

    private static int indexOfLastSeparator(String filename) {
        if (filename == null) {
            return -1;
        }
        int lastUnixPos = filename.lastIndexOf(File.separatorChar);
        int lastWindowsPos = filename.lastIndexOf('\\');
        return Math.max(lastUnixPos, lastWindowsPos);
    }

    public static void main(String[] args) {
        // Example usage
        System.out.println(indexOfExtension("example.tar.gz")); // Output: 11
        System.out.println(indexOfExtension("example")); // Output: -1
        System.out.println(indexOfExtension("example/with/path.tar.gz")); // Output: 17
        System.out.println(indexOfExtension("example\\with\\path.tar.gz")); // Output: 17
        System.out.println(indexOfExtension("example\\with\\path")); // Output: -1
    }
}
